/**
 * @summary List all passengers
 */
export const getListPassengersUrl = (params?: ListPassengersParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/passengers?${stringifiedParams}`
    : `/api/passengers`;
};

export const listPassengers = async (
  params?: ListPassengersParams,
  options?: RequestInit,
): Promise<Passenger[]> => {
  return customFetch<Passenger[]>(getListPassengersUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListPassengersQueryKey = (params?: ListPassengersParams) => {
  return [`/api/passengers`, ...(params ? [params] : [])] as const;
};

export const getListPassengersQueryOptions = <
  TData = Awaited<ReturnType<typeof listPassengers>>,
  TError = ErrorType<unknown>,
>(
  params?: ListPassengersParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listPassengers>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getListPassengersQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listPassengers>>> = ({
    signal,
  }) => listPassengers(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof listPassengers>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ListPassengersQueryResult = NonNullable<
  Awaited<ReturnType<typeof listPassengers>>
>;
export type ListPassengersQueryError = ErrorType<unknown>;

